def transforms(cells):
    out=[]
    for m in [(1,1),(1,-1),(-1,1),(-1,-1)]:
        for swap in [False,True]:
            t=sorted((r*m[0],c*m[1]) if not swap else (c*m[1],r*m[0]) for r,c in cells)
            mr=min(r for r,c in t); mc=min(c for r,c in t)
            t=sorted((r-mr,c-mc) for r,c in t)
            if t not in out: out.append(t)
    return out

